*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gIsurCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    /*
    02549-상장폐지 실질심사 사유코드
    */
    var arrCid = [{
        cid: "DELIST_REAL_INVSTG_RSN_CD",
        cnm: "cmb_DELIST_REAL_INVSTG_RSN_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=ULDSTF20502.gfm&SCREN_PROCES_TP_CD=01&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='DELIST_REAL_INVSTG_RSN_CD','DELIST_REAL_INVSTG_MISC_CD','AUDT_OPIN_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^전체,";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT").replace(/,/g, "','");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_list_sync = function() {
    var vMarketTpCd = "";
    if (js_market == "1" || js_market == "2") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD);
    }
    var url = "/listingCommon.do?SCREN_ID=ULDSTF20505.gfm&SCREN_PROCES_TP_CD=01&method=listGeneral" + "&outputMessageId=REALINVSTG_SEARCH_NEW" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.delist.forminvstg.condition" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&{P}param02=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&{P}param03=" + vMarketTpCd + "&{P}param04=" + vMarketTpCd + "&{P}param05=" + $c.stf.getObjectValue(cmb_DELIST_REAL_INVSTG_RSN_CD) + "&{P}param06=" + $c.stf.getObjectValue(cmb_DELIST_REAL_INVSTG_RSN_CD) + "&{P}param07=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param08=" + $c.stf.getObjectValue(edt_EDate);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_setGrdCode = function() {
    var strCbdReason = "' ':"; //초기값
    var strAudtOpin = "' ':";
    for (k = 1; k <= dts_Cod.getTotalRow(); k++) {
        if (dts_Cod.getCellData(k, "CD_ENG_NM") == "DELIST_REAL_INVSTG_MISC_CD") {
            strCbdReason = strCbdReason + (strCbdReason == "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
        } else if (dts_Cod.getCellData(k, "CD_ENG_NM") == "AUDT_OPIN_TP_CD") {
            strAudtOpin = strAudtOpin + (strAudtOpin == "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
        }
    }
    $c.cm.setColumnProp(grd_Grid, 'DELIST_REAL_INVSTG_MISC_CD', 'Data', strCbdReason);
    $c.cm.setColumnProp(grd_Grid, 'THSBZYY_AUDT_OPIN_TP_CD', 'Data', strAudtOpin);
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave("ULDSTF20505.gfm", SCREN_PROCS_TP_CD_07);
    //grd_Grid.GridToExcel("형식상장폐지 이의신청심 법인현황", "", "8");
    $c.data.downloadGridViewOffice(grd_Grid, "형식상장폐지 이의신청심 법인현황", "", 128, 0);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    //edt_SDate.text = cGetMinusDate2(vCurDate, 7);
    edt_SDate.setValue("20110101");
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    if (js_market == "1" || js_market == "2") {
        $c.stf.showObj(panel_mkt_gubun, false);
    } else {
        $c.stf.showObj(panel_mkt_gubun, true);
    }
    scwin.fn_SetCode();
    scwin.fn_setGrdCode();
    cmb_DELIST_REAL_INVSTG_RSN_CD.BindColVal = "";
    scwin.fn_list_sync();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (colid == "COM_ABBRV") {
        scwin.gIsurCd = dts_List.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    }
};
